import socket
import ssl
from tls_client import make_client_context


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert against cafile and hostname,
    and return the server's greeting bytes up to and including the first newline or up to 4096 bytes."""
    if server_hostname is None:
        server_hostname = host
    ctx = make_client_context(cafile)
    with socket.create_connection((host, port)) as sock:
        with ctx.wrap_socket(sock, server_hostname=server_hostname) as tls_sock:
            # Read up to 4096 bytes or until a newline is found
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    break
            # Return bytes up to and including the first newline, or all if none
            nl_index = data.find(b"\n")
            if nl_index >= 0:
                return bytes(data[: nl_index + 1])
            return bytes(data)

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert and hostname, return greeting bytes.

    The greeting is the bytes received up to and including the first newline byte, or until the server
    closes the connection, up to 4096 bytes max.

    Raises ssl.SSLError or ssl.CertificateError on verification failure.
    """
    if server_hostname is None:
        server_hostname = host

    with socket.create_connection((host, port)) as sock:
        tls_sock = wrap_client_socket(sock, server_hostname, cafile=cafile)
        # Read up to 4096 bytes or until newline
        data = bytearray()
        while len(data) < 4096:
            chunk = tls_sock.recv(4096 - len(data))
            if not chunk:
                # Connection closed by server
                break
            data.extend(chunk)
            if b"\n" in chunk:
                # Stop after the first newline
                break
        # Return up to and including the first newline
        newline_pos = data.find(b"\n")
        if newline_pos >= 0:
            return bytes(data[:newline_pos + 1])
        else:
            return bytes(data)

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert and hostname, return greeting bytes.

    The greeting is the bytes received up to and including the first newline byte b'\n',
    or up to 4096 bytes if no newline is received before connection close.

    Raises ssl.SSLError or ssl.CertificateError on verification failure.
    """
    if server_hostname is None:
        server_hostname = host

    with socket.create_connection((host, port)) as sock:
        tls_sock = wrap_client_socket(sock, server_hostname=server_hostname, cafile=cafile)
        try:
            # Read up to 4096 bytes or until newline is found
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    # Connection closed
                    break
                data.extend(chunk)
                if b'\n' in chunk:
                    # Stop reading after newline
                    break
            # Return up to and including the first newline if present
            idx = data.find(b'\n')
            if idx != -1:
                return bytes(data[:idx + 1])
            else:
                return bytes(data)
        finally:
            tls_sock.close()
